    string tok;
    while(getline(ss,tok,',')) pq.push(stoi(tok));
    while(pq.size()>1) {
        int y=pq.top(); pq.pop();
        int x=pq.top(); pq.pop();
        if(y!=x) pq.push(y-x);
    }
    cout<<(pq.empty()?0:pq.top())<<endl;
}

